'use client';

import { cn } from 'cn';
import type { ListType } from 'platejs';
import {
  ListPlugin,
  type RenderNodeWrapper,
  useEditor,
  useEditorReadOnly,
} from 'platejs/react';
import React from 'react';

import { Checkbox } from '@/components/ui/checkbox';

type ListWrapper = RenderNodeWrapper<typeof ListPlugin>;

export const BlockList: ListWrapper = (props) => {
  const { listStyle, listType } = props.element;

  if (!listType || listType === 'bulleted') return undefined;

  return function BlockListWrapper(innerProps) {
    return (
      <List
        {...innerProps}
        listStart={
          listType === 'numbered'
            ? innerProps.editor
                .plugin(ListPlugin)
                .read.ordinal(innerProps.element)
            : undefined
        }
        listStyle={listStyle}
        listType={listType}
      />
    );
  };
};

function List(
  props: Parameters<ListWrapper>[0] & {
    lineBreakBadge?: React.ReactNode;
    listStart?: number;
    listStyle?: string;
    listType: ListType;
  }
) {
  const { listStart, listStyle, listType } = props;
  const isTask = listType === 'task';
  const isNumbered = listType === 'numbered';
  const InnerList = isNumbered ? 'ol' : 'ul';
  const markerStyle =
    isNumbered && listStart === undefined
      ? 'none'
      : (listStyle ?? (isNumbered ? 'decimal' : 'none'));

  return (
    <InnerList
      className="relative m-0 p-0"
      data-list-id={props.element.listId ?? ''}
      data-list-levels={
        props.element.listLevels
          ? JSON.stringify(props.element.listLevels)
          : undefined
      }
      style={{ listStyleType: markerStyle }}
      start={isNumbered ? listStart : undefined}
    >
      <li
        className={
          isTask
            ? cn(
                'list-none',
                props.element.checked === true &&
                  'text-muted-foreground line-through'
              )
            : undefined
        }
      >
        {isTask && <TodoMarker {...props} />}
        {props.children}
        {props.lineBreakBadge}
      </li>
    </InnerList>
  );
}

function TodoMarker(
  props: Parameters<ListWrapper>[0] & {
    lineBreakBadge?: React.ReactNode;
    listStart?: number;
    listStyle?: string;
    listType: ListType;
  }
) {
  const editor = useEditor();
  const readOnly = useEditorReadOnly();

  return (
    <div
      className="absolute -start-6 top-1 select-none"
      contentEditable={false}
    >
      <Checkbox
        aria-label={
          props.element.checked === true
            ? 'Mark task incomplete'
            : 'Mark task complete'
        }
        className={cn(readOnly && 'pointer-events-none')}
        checked={props.element.checked === true}
        onCheckedChange={(value) => {
          if (readOnly) return;

          editor
            .update({ history: 'new-batch' })
            .nodes.set({ checked: value }, { at: props.element });
        }}
        onMouseDown={(event) => {
          event.preventDefault();
        }}
      />
    </div>
  );
}
